// Corylus wallpaper gallery — plain JS, hash-routed, no framework/bundler.
// Loads gallery-index.json (generated by scripts/build_gallery.py) and
// renders: landing (categories by kind) -> folder (item grid) -> lightbox.

(function () {
  "use strict";

  const KIND_LABELS = { image: "Images", video: "Videos", animated: "Animated" };
  const REDUCED_MOTION = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  let ITEMS = [];
  const app = document.getElementById("app");
  const breadcrumb = document.getElementById("breadcrumb");
  const lightbox = document.getElementById("lightbox");
  const lightboxContent = document.getElementById("lightbox-content");
  const lightboxMeta = document.getElementById("lightbox-meta");
  const lightboxClose = document.getElementById("lightbox-close");

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
    }[c]));
  }

  // ── Data ──────────────────────────────────────────────────────────────────

  function groupByKindAndCategory(items) {
    const byKind = new Map();
    for (const item of items) {
      if (!byKind.has(item.kind)) byKind.set(item.kind, new Map());
      const byCat = byKind.get(item.kind);
      if (!byCat.has(item.category)) byCat.set(item.category, []);
      byCat.get(item.category).push(item);
    }
    return byKind;
  }

  // ── Lazy preview loading (IntersectionObserver) ──────────────────────────

  const lazyObserver = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const el = entry.target;
        lazyObserver.unobserve(el);
        if (el.tagName === "VIDEO") {
          const src = el.dataset.src;
          if (src && !el.src) {
            el.src = src;
            if (!REDUCED_MOTION) el.play().catch(() => {});
          }
        } else if (el.tagName === "IMG") {
          if (el.dataset.src && !el.src) el.src = el.dataset.src;
        }
      }
    },
    { rootMargin: "200px" },
  );

  // ── Rendering ─────────────────────────────────────────────────────────────

  function renderLanding() {
    breadcrumb.innerHTML = "";
    const byKind = groupByKindAndCategory(ITEMS);
    const order = ["image", "video", "animated"];
    let html = "";
    for (const kind of order) {
      const byCat = byKind.get(kind);
      if (!byCat) continue;
      html += `<section class="kind-group"><h2>${KIND_LABELS[kind] || kind}</h2><div class="category-grid">`;
      for (const [category, items] of [...byCat.entries()].sort()) {
        const cover = items[0];
        const coverSrc = cover.kind === "video" ? "" : cover.thumbUrl;
        html += `
          <a class="category-card" href="#/${kind}/${encodeURIComponent(category)}">
            ${coverSrc
              ? `<img class="category-card__thumb" loading="lazy" src="${escapeHtml(coverSrc)}" alt="">`
              : `<div class="category-card__thumb"></div>`}
            <div class="category-card__label">${escapeHtml(category)} <span class="count">(${items.length})</span></div>
          </a>`;
      }
      html += `</div></section>`;
    }
    app.innerHTML = html || `<p class="empty-state">No media found.</p>`;
  }

  function renderFolder(kind, category) {
    const items = ITEMS.filter((i) => i.kind === kind && i.category === category);
    breadcrumb.innerHTML = `<a href="#/">All categories</a> &rsaquo; <span class="current">${escapeHtml(KIND_LABELS[kind] || kind)} / ${escapeHtml(category)}</span>`;

    if (items.length === 0) {
      app.innerHTML = `<p class="empty-state">Nothing here.</p>`;
      return;
    }

    let html = `<div class="item-grid">`;
    items.forEach((item, idx) => {
      if (item.kind === "video") {
        html += `
          <div class="item-tile" data-idx="${idx}" data-kind="${kind}" data-category="${escapeHtml(category)}">
            <video muted loop playsinline preload="none" data-src="${escapeHtml(item.thumbUrl)}"></video>
            <span class="item-tile__badge">&#9654;</span>
          </div>`;
      } else {
        html += `
          <div class="item-tile" data-idx="${idx}" data-kind="${kind}" data-category="${escapeHtml(category)}">
            <img loading="lazy" data-src="${escapeHtml(item.thumbUrl)}" alt="${escapeHtml(item.filename)}">
          </div>`;
      }
    });
    html += `</div>`;
    app.innerHTML = html;

    app.querySelectorAll(".item-tile").forEach((tile) => {
      const media = tile.querySelector("video, img");
      lazyObserver.observe(media);
      tile.addEventListener("click", () => openLightbox(items[Number(tile.dataset.idx)]));
    });
  }

  // ── Lightbox ──────────────────────────────────────────────────────────────

  function openLightbox(item) {
    let mediaHtml;
    if (item.kind === "video") {
      mediaHtml = `<video src="${escapeHtml(item.rawUrl)}" controls autoplay loop playsinline></video>`;
    } else {
      mediaHtml = `<img src="${escapeHtml(item.rawUrl)}" alt="${escapeHtml(item.filename)}">`;
    }
    lightboxContent.innerHTML = mediaHtml;

    let metaHtml = `<div class="filename">${escapeHtml(item.filename)} &middot; ${escapeHtml(item.category)}</div>`;
    if (item.credit && item.credit.author) {
      const authorLink = item.credit.authorUrl
        ? `<a href="${escapeHtml(item.credit.authorUrl)}" target="_blank" rel="noopener">${escapeHtml(item.credit.author)}</a>`
        : escapeHtml(item.credit.author);
      const licenseText = item.credit.license ? ` &middot; ${escapeHtml(item.credit.license)}` : "";
      metaHtml += `<div class="credit">By ${authorLink}${licenseText}</div>`;
    }
    metaHtml += `<a class="download" href="${escapeHtml(item.rawUrl)}" download>Download</a>`;
    lightboxMeta.innerHTML = metaHtml;

    lightbox.hidden = false;
    document.body.style.overflow = "hidden";
  }

  function closeLightbox() {
    lightbox.hidden = true;
    lightboxContent.innerHTML = ""; // stop any playing video
    document.body.style.overflow = "";
  }

  lightboxClose.addEventListener("click", closeLightbox);
  lightbox.addEventListener("click", (e) => { if (e.target === lightbox) closeLightbox(); });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !lightbox.hidden) closeLightbox();
  });

  // ── Router ────────────────────────────────────────────────────────────────

  function route() {
    closeLightbox();
    const hash = window.location.hash.replace(/^#\/?/, "");
    const parts = hash.split("/").filter(Boolean).map(decodeURIComponent);
    if (parts.length >= 2) {
      renderFolder(parts[0], parts[1]);
    } else {
      renderLanding();
    }
  }

  window.addEventListener("hashchange", route);

  // ── Boot ──────────────────────────────────────────────────────────────────

  fetch("gallery-index.json")
    .then((r) => r.json())
    .then((items) => {
      ITEMS = items;
      route();
    })
    .catch((err) => {
      app.innerHTML = `<p class="empty-state">Failed to load the gallery index: ${escapeHtml(String(err))}</p>`;
    });
})();
